const { generateQRModules } = require('../module/qr-code');

/**
 * Helper: flatten QR modules to a binary string for comparison.
 */
function toBinaryString(modules, size) {
    let s = '';
    for (let y = 0; y < size; y++) {
        for (let x = 0; x < size; x++) {
            s += modules[y][x] ? '1' : '0';
        }
    }
    return s;
}

// These reference strings were generated by running lean-qr (reference/lean-qr)
// with mode.ascii() and EC level L (minCorrectionLevel: 0, maxCorrectionLevel: 0).
const REFERENCE = {
    Hello: {
        size: 21,
        data: ''
    },
    'http://192.168.1.50:18881/download-ca': {
        size: 29,
        data: ''
    },
    Ver1: {
        size: 21,
        data: ''
    }
};

describe('QR Code Generator (lean-qr port)', () => {
    describe('generateQRModules basic properties', () => {
        it('should produce a square module matrix', () => {
            const { modules, size } = generateQRModules('test');
            expect(modules.length).toBe(size);
            modules.forEach((row) => expect(row.length).toBe(size));
        });

        it('should produce version-1 size (21x21) for short text', () => {
            const { size, version } = generateQRModules('Hi');
            expect(version).toBe(1);
            expect(size).toBe(21);
        });

        it('should only contain 0s and 1s', () => {
            const { modules } = generateQRModules('http://192.168.1.1:18881/download-ca');
            for (const row of modules) {
                for (const cell of row) {
                    expect(cell === 0 || cell === 1).toBe(true);
                }
            }
        });

        it('should produce deterministic output', () => {
            const r1 = generateQRModules('hello world');
            const r2 = generateQRModules('hello world');
            expect(r1.modules).toEqual(r2.modules);
        });

        it('should produce different output for different input', () => {
            const r1 = generateQRModules('aaa');
            const r2 = generateQRModules('bbb');
            expect(toBinaryString(r1.modules, r1.size)).not.toBe(toBinaryString(r2.modules, r2.size));
        });

        it('size should equal version * 4 + 17', () => {
            const { size, version } = generateQRModules('http://192.168.1.100:18881/download-ca');
            expect(size).toBe(version * 4 + 17);
        });
    });

    describe('finder patterns', () => {
        it('should have correct top-left finder pattern', () => {
            const { modules } = generateQRModules('test');
            // Row 0: all 7 dark
            for (let c = 0; c < 7; c++) expect(modules[0][c]).toBe(1);
            // Row 1: dark, 5 light, dark
            expect(modules[1][0]).toBe(1);
            for (let c = 1; c < 6; c++) expect(modules[1][c]).toBe(0);
            expect(modules[1][6]).toBe(1);
        });

        it('should have correct top-right finder pattern', () => {
            const { modules, size } = generateQRModules('test');
            for (let c = size - 7; c < size; c++) expect(modules[0][c]).toBe(1);
            expect(modules[1][size - 7]).toBe(1);
            for (let c = size - 6; c < size - 1; c++) expect(modules[1][c]).toBe(0);
            expect(modules[1][size - 1]).toBe(1);
        });

        it('should have correct bottom-left finder pattern', () => {
            const { modules, size } = generateQRModules('test');
            for (let c = 0; c < 7; c++) expect(modules[size - 1][c]).toBe(1);
            expect(modules[size - 2][0]).toBe(1);
            for (let c = 1; c < 6; c++) expect(modules[size - 2][c]).toBe(0);
            expect(modules[size - 2][6]).toBe(1);
        });
    });

    describe('exact match with lean-qr reference output', () => {
        for (const [text, expected] of Object.entries(REFERENCE)) {
            it(`should match reference for "${text.length > 20 ? text.slice(0, 20) + '...' : text}"`, () => {
                const { modules, size } = generateQRModules(text);
                expect(size).toBe(expected.size);
                const actual = toBinaryString(modules, size);
                expect(actual).toBe(expected.data);
            });
        }
    });
});
